$$
begin
  update parent set bcnt = bcnt + 1 where aid = new.aid;
  return new;
end;
$$

create function child_del_func()
  returns trigger language plpgsql as
$$
begin
  update parent set bcnt = bcnt - 1 where aid = old.aid;
